def choose_move(observation):
    sx, sy = observation.get("self_position", (0, 0))
    ox, oy = observation.get("opponent_position", (0, 0))
    grid_width = observation.get("grid_width", 10)
    grid_height = observation.get("grid_height", 10)
    resources = observation.get("resources", [])
    obstacles = set(observation.get("obstacles", []))
    remaining = observation.get("remaining_resource_count", 0)
    self_path = set(observation.get("self_path", []))

    def safe_move(dx, dy):
        nx, ny = sx + dx, sy + dy
        if 0 <= nx < grid_width and 0 <= ny < grid_height:
            if (nx, ny) not in obstacles:
                return True
        return False

    # prioritize moving toward nearest resource if any
    if resources:
        nearest = min(resources, key=lambda c: abs(c[0]-sx)+abs(c[1]-sy))
        dx = 0 if nearest[0]==sx else (1 if nearest[0]>sx else -1)
        dy = 0 if nearest[1]==sy else (1 if nearest[1]>sy else -1)
        if safe_move(dx, dy):
            return [dx, dy]
        # try alternative directions if blocked
        for ndx, ndy in [(dx,0),(0,dy),(-dx,0),(0,-dy)]:
            if safe_move(ndx, ndy):
                return [ndx, ndy]

    # move away from opponent to avoid collision
    dx = 0
    dy = 0
    if abs(ox - sx) > abs(oy - sy):
        dx = 1 if ox < sx else -1
    else:
        dy = 1 if oy < sy else -1

    if safe_move(dx, dy):
        return [dx, dy]
    # fallback: try to stay still
    if safe_move(0,0):
        return [0,0]
    # try moving in any safe direction
    for dx_test in [-1,0,1]:
        for dy_test in [-1,0,1]:
            if safe_move(dx_test, dy_test):
                return [dx_test, dy_test]
    # default to no move
    return [0,0]
